public class Main {

    static int count = 0;

    // Static block
    static {
        System.out.println("Static block: class loaded");
    }

    // Instance block
    {
        count++;
        System.out.println("Instance block: object #" + count + " created");
    }

    // Constructor
    Main() {
        System.out.println("Constructor: building object #" + count);
    }

    public static void main(String[] args) {
        System.out.println("main() started");
        new Main();
        new Main();
        System.out.println("Total objects: " + count);
    }
}
